package org.apache.commons.io.input.buffer;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class CircularByteBuffer_ESTest_test12 extends CircularByteBuffer_ESTest_scaffolding {

    /**
     * Verifies that {@link CircularByteBuffer#peek(byte[], int, int)} rejects a
     * negative length by throwing an {@link IllegalArgumentException}.
     */
    @Test(timeout = 4000)
    public void peekWithNegativeLengthThrowsIllegalArgumentException() throws Throwable {
        CircularByteBuffer buffer = new CircularByteBuffer();
        byte[] sourceBuffer = new byte[3];
        int validOffset = 0;
        int negativeLength = -2186;

        try {
            buffer.peek(sourceBuffer, validOffset, negativeLength);
            fail("Expecting exception: IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            // The message is "Illegal length: -2186".
            verifyException("org.apache.commons.io.input.buffer.CircularByteBuffer", e);
        }
    }
}
